<?php
namespace App\Http\Controllers\Api;use App\Models\EventType;use Illuminate\Http\Request;class EventTypeController extends Controller{public function index(Request $r){$q=EventType::query();if($r->search)$q->where('name','like','%'.$r->search.'%');return $this->ok($q->latest()->paginate($r->integer('per_page',15)));}public function store(Request $r){$i=EventType::create($r->all());return $this->ok($i,'Created');}public function show(EventType $eventType){return $this->ok($eventType);}public function update(Request $r,EventType $eventType){$eventType->update($r->all());return $this->ok($eventType,'Updated');}public function destroy(EventType $eventType){$eventType->delete();return $this->ok(null,'Deleted');}}
